package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.io.ByteArrayOutputStream;
import java.io.File;
import java.io.IOException;
import java.io.OutputStream;
import java.math.*;
import java.util.*;
import org.apache.commons.compress.archivers.ArchiveEntry;
import org.apache.commons.compress.archivers.ArchiveOutputStream;
import org.junit.*;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class TarArchiveOutputStream_putArchiveEntry_TriageGen0Test {

    private ByteArrayOutputStream out;
    private TarArchiveOutputStream tarStream;

    // Constants based on TarConstants if available, or assumed based on logic
    private static final int NAMELEN = 100; 
    private static final int LONGFILE_GNU = 1;
    private static final int LONGFILE_TRUNCATE = 2;
    private static final int GNU_LONGLINK = 0; // Placeholder for testing
    private static final int LF_GNUTYPE_LONGNAME = 0; // Placeholder for testing

    @Before
    public void setUp() throws IOException {
        out = new ByteArrayOutputStream();
        tarStream = new TarArchiveOutputStream(out);
    }

    @Test
    public void testPutArchiveEntry_NormalName() throws IOException {
        TarArchiveEntry entry = new TarArchiveEntry("normal.txt");
        entry.setSize(10);

        tarStream.putArchiveEntry(entry);

        // Verify no exception and state updated
        // Since we can't easily inspect private fields without reflection, 
        // we ensure the method completes successfully.
    }

    @Test
    public void testPutArchiveEntry_Directory_NormalName() throws IOException {
        TarArchiveEntry entry = new TarArchiveEntry("dir/");
        entry.setDirectory(true);

        tarStream.putArchiveEntry(entry);
        // Should set currSize to 0 for directories
    }

    @Test
    public void testPutArchiveEntry_LongName_TruncateMode() throws IOException {
        // Create a name longer than NAMELEN
        StringBuilder longNameBuilder = new StringBuilder();
        for (int i = 0; i < NAMELEN + 10; i++) {
            longNameBuilder.append("a");
        }
        String longName = longNameBuilder.toString();

        TarArchiveEntry entry = new TarArchiveEntry(longName);
        entry.setSize(10);

        tarStream.setLongFileMode(LONGFILE_TRUNCATE);

        // In TRUNCATE mode, it should not throw exception but proceed to write header (potentially truncated by internal logic)
        tarStream.putArchiveEntry(entry);
    }

    @Test(expected = RuntimeException.class)
    public void testPutArchiveEntry_LongName_DefaultMode_ThrowsException() throws IOException {
        StringBuilder longNameBuilder = new StringBuilder();
        for (int i = 0; i < NAMELEN + 10; i++) {
            longNameBuilder.append("a");
        }
        String longName = longNameBuilder.toString();

        TarArchiveEntry entry = new TarArchiveEntry(longName);

        // Default mode is usually not GNU or Truncate
        tarStream.setLongFileMode(0); 

        tarStream.putArchiveEntry(entry);
    }

    @Test
    public void testPutArchiveEntry_LongName_GnuMode() throws IOException {
        // Mocking or using a real TarArchiveEntry with a very long name
        StringBuilder longNameBuilder = new StringBuilder();
        for (int i = 0; i < NAMELEN + 10; i++) {
            longNameBuilder.append("a");
        }
        String longName = longNameBuilder.toString();

        TarArchiveEntry entry = new TarArchiveEntry(longName);
        entry.setSize(5);

        tarStream.setLongFileMode(LONGFILE_GNU);

        // This should trigger the LongLink logic:
        // 1. Create longLinkEntry
        // 2. putArchiveEntry(longLinkEntry)
        // 3. write(nameBytes)
        // 4. write(0)
        // 5. closeArchiveEntry()
        // 6. Finally write the original entry header
        tarStream.putArchiveEntry(entry);

        Assert.assertTrue("Output should not be empty", out.size() > 0);
    }

    @Test
    public void testPutArchiveEntry_SizeHandling() throws IOException {
        TarArchiveEntry entry = new TarArchiveEntry("file.txt");
        long size = 12345L;
        entry.setSize(size);

        tarStream.putArchiveEntry(entry);
        // Logic check: currSize should be set to entry.getSize()
    }

    @Test
    public void testPutArchiveEntry_LargeFileMode_NotGNU_NotTruncate_Throws() throws IOException {
        // To ensure we hit the specific branch: if (longFileMode != LONGFILE_TRUNCATE)
        // We use a mode that is neither GNU nor TRUNCATE
        StringBuilder longNameBuilder = new StringBuilder();
        for (int i = 0; i < 101; i++) {
            longNameBuilder.append("b");
        }
        String longName = longNameBuilder.toString();
        TarArchiveEntry entry = new TarArchiveEntry(longName);

        tarStream.setLongFileMode(999); // Arbitrary mode

        try {
            tarStream.putArchiveEntry(entry);
            Assert.fail("Should have thrown RuntimeException due to long name and unsupported mode");
        } catch (RuntimeException e) {
            Assert.assertTrue(e.getMessage().contains("is too long"));
        }
    }
}
